    const defaultDarkLanding = variant === "landing-screenshots-stats" || variant === "landing-bg-hero-pricing"
    const isDarkLanding = theme === "dark" || (theme === "system" && defaultDarkLanding)
    const landingTheme = isDarkLanding ? "dark" : "light"
    const openLandingAction = (label: string, feedback = `${label} opened`) => {
      setActiveNavItem(label)
      setPostedComment(feedback)
    }
    const LandingRoot = ({ children, className }: { children: ReactNode; className?: string }) => (
      <div data-landing-page-theme={landingTheme} data-landing-page-variant={variant} className={className}>{children}</div>
    )
