    if (variant === "calendar-week-view") return <div className="bg-background p-5 md:p-8"><div className="mx-auto max-w-5xl"><WeekGrid /></div></div>
    if (variant === "calendar-day-view") return <div className={cn("p-5 md:p-8", isDark ? "bg-slate-950" : "bg-background")}><div className="mx-auto max-w-5xl"><DayView /></div></div>
    if (variant === "calendar-year-view") return <div className={cn("p-5 md:p-8", isDark ? "bg-slate-950" : "bg-background")}><div className={cn("mx-auto max-w-5xl rounded-md border p-6", isDark ? "border-white/10 bg-slate-900" : "bg-white")}><YearView />{postedComment && <p className={cn("mt-4 rounded-md px-3 py-2 text-xs font-medium", isDark ? "bg-white/10 text-indigo-200" : "bg-indigo-50 text-indigo-700")}>{postedComment}</p>}</div></div>
