    if (variant === "table-list-card") return <Shell><Header /><div className={cn("overflow-hidden rounded-md ring-1", isDark ? "bg-slate-900 ring-white/10" : "bg-white ring-slate-200")}><UsersTable dark={isDark} /></div></Shell>
    if (variant === "table-list-striped") return <Shell><Header /><UsersTable dark={isDark} striped /></Shell>
    if (variant === "table-list-uppercase") return <Shell><Header /><UsersTable dark={isDark} uppercase /></Shell>
    if (variant === "table-list-stacked-mobile") return <Shell><Header /><UsersTable dark={isDark} mobileMode="stacked" /></Shell>
    if (variant === "table-list-hidden-mobile") return <Shell><Header /><UsersTable dark={isDark} mobileMode="hidden" /></Shell>
    if (variant === "table-list-avatars-multiline") return <Shell><Header /><UsersTable dark={isDark} avatars multiline /></Shell>
