    const isSubtle = variant === "shell-stacked-subtle-background"
    const isBrand = variant === "shell-stacked-brand-compact-header" || variant === "shell-stacked-brand-overlap" || variant === "shell-stacked-brand-lighter-header"
    const hasOverlap = variant === "shell-stacked-overlap" || variant === "shell-stacked-brand-overlap" || variant === "shell-stacked-two-row-overlap"
    const isCompact = variant === "shell-stacked-brand-compact-header" || variant === "shell-stacked-compact-header"
    const isTwoRow = variant === "shell-stacked-two-row-overlap"
    const hasBottomBorder = variant === "shell-stacked-bottom-border" || variant === "shell-stacked-brand-lighter-header"
    const hasSidebarHeader = variant === "shell-sidebar-with-header" || variant === "shell-sidebar-dark-with-header" || variant === "shell-sidebar-brand-with-header"
    const isDarkSidebar = variant === "shell-sidebar-simple" || variant === "shell-sidebar-dark" || variant === "shell-sidebar-dark-with-header"
    const isFullDarkSidebar = variant === "shell-sidebar-simple"
    const isBrandSidebar = variant === "shell-sidebar-brand" || variant === "shell-sidebar-brand-with-header"
    const isConstrainedSidebar = variant === "shell-sidebar-constrained"
