    const sidebarNavItems = ["Dashboard", "Team", "Projects", "Calendar", "Documents", "Reports"]
    const sidebarActive = sidebarNavItems.includes(activeNavItem) ? activeNavItem : "Dashboard"
    const shellTabs = ["Overview", "Activity", "Settings"]
    const shellTab = shellTabs.includes(catalogTab) ? catalogTab : "Overview"
    const stackedMobileMenuId = `${variant}-mobile-menu`
