                <button key={item} aria-current={shellActive === item ? "page" : undefined} className={cn("rounded-md px-3 py-2 text-sm font-medium transition hover:-translate-y-0.5 hover:bg-white/10 hover:text-white active:scale-[0.98]", shellActive === item ? "bg-black/20 text-white" : "text-white/70")} type="button" onClick={() => { setActiveNavItem(item); setPostedComment(`${item} opened`) }}>{item}</button>
