          <main className={cn("p-8", isFullDarkSidebar ? "bg-slate-950" : isOffWhiteSidebar ? "bg-slate-100" : "bg-white")}>
            <div className={cn("h-full min-h-[520px] rounded-xl border border-dashed p-8 shadow-inner transition", isFullDarkSidebar ? "border-white/10 bg-slate-900 text-white" : "border-slate-300 bg-slate-50 text-slate-950")}>
              <p className="text-sm font-semibold">{sidebarActive}</p>
              <p className={cn("mt-2 text-sm", isFullDarkSidebar ? "text-slate-400" : "text-slate-500")}>Selected shell section updates without moving the layout.</p>
              {postedComment && <p className={cn("mt-3 rounded-md px-3 py-2 text-xs font-medium", isFullDarkSidebar ? "bg-white/10 text-indigo-100" : "bg-indigo-50 text-indigo-700")}>{postedComment}</p>}
            </div>
          </main>
