          <div className={cn("flex items-center gap-4", isCartPageDark ? "text-slate-300" : "text-slate-500")}>{[
            { Icon: Search, label: "Search", feedback: "Search opened" },
            { Icon: UserRound, label: "Account", feedback: "Account opened" },
            { Icon: ShoppingCart, label: "Cart", feedback: "Cart opened" },
          ].map(({ Icon, label, feedback }) => <button key={label} aria-label={`Open cart ${label}`} aria-pressed={activeNavItem === `cart-${label}`} className="rounded-md p-1 transition hover:bg-indigo-50 hover:text-indigo-600 active:scale-95 aria-pressed:bg-indigo-500/10 aria-pressed:text-indigo-600" type="button" onClick={() => selectCartPageAction(`cart-${label}`, feedback)}><Icon className="size-4" /></button>)}</div>
